head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = "ULDSTF05950.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.flagVal;
scwin.TR_JOB;
scwin.ELW_MBR_INFO_TP_CD;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetTitle = function() {
    var strTitle = "";
    txa_Title.setReadOnly(false);
    if (scwin.ELW_MBR_INFO_TP_CD == 6 || scwin.ELW_MBR_INFO_TP_CD == 7) {
        $c.stf.showObj(txa_Title, false);
    } else {
        $c.stf.showObj(txa_Title, true);
    }
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        $c.stf.showObj(chk_DelYn, true);
        $c.stf.showObj(label_14, true);
    } else {
        $c.stf.showObj(chk_DelYn, false);
        $c.stf.showObj(label_14, false);
    }
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        strTitle = "* 발행사가 코드 발급한 ELW의 기초자산이 제한사유 해당종목이고 만기가 제한사유 발생시점 이후에 도래하는 경우\r\n  상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        strTitle = "* 발행사가 조회화면에 저장되어 있는 종목을 코드발급한 경우, 상장공시제출시스템의 상장신청 탭을 선택하였을때 안내 메시지를 표시합니다.";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 3) {
        //strTitle = "* 매월 첫 영업일에 전월 말일 기준으로 코스닥150 구성종목중 시가총위 5위 이내의 종목을 자동으로 저장합니다.";
        strTitle = "";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
        strTitle = "* 지정한 표시기간 동안 발행사 담당자가 상장공시제출시스템의 공시제출 탭을 선택했을 때 팝업화면으로 내용에 입력한 사항을 표시합니다.";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
        strTitle = "* 메시지 표시기간은 입력값이 없으면 매월 말일 포함 직전 3영업일입니다.";
    }
    $c.stf.setObjectValue(txa_Title, strTitle);
    txa_Title.setReadOnly(true);
};
scwin.fn_setYYYYMM = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var YYMM = vCurDate.substr(0, 6);
    $c.stf.setObjectValue(txb_YYYYMM, YYMM);
};
scwin.fn_SetDataHeader = function() {
    if (scwin.ELW_MBR_INFO_TP_CD == 1 || scwin.ELW_MBR_INFO_TP_CD == 2) {
        dts_Item.removeAll();
        //dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        //껍데기만 만들고 사용자필드를 사용함
        dts_Item.insertRow();
    } else if (scwin.ELW_MBR_INFO_TP_CD == 3) {
        dts_Item.removeAll();
        //dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        //껍데기만 만들고 사용자필드를 사용함
        dts_Item.insertRow();
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4 || scwin.ELW_MBR_INFO_TP_CD == 5) {
        dts_Item.removeAll();
        //dts_Item.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        //껍데기만 만들고 사용자필드를 사용함
        dts_Item.insertRow();
    }
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        arrPar[0] = txb_ISUR_CD_1.getValue(); // 발행기관코드값
        arrPar[1] = txb_COM_NM_1.getValue(); // 발행기관명

    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        arrPar[0] = txb_ISUR_CD_2.getValue(); // 발행기관코드값
        arrPar[1] = txb_COM_NM_2.getValue(); // 발행기관명

    }
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        if (scwin.ELW_MBR_INFO_TP_CD == 1) {
            txb_ISUR_CD_1.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM_1.setValue(arrPar[0].COM_NM);
        } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
            txb_ISUR_CD_2.setValue(arrPar[0].ISUR_CD);
            txb_COM_NM_2.setValue(arrPar[0].COM_NM);
        }
    }
};
scwin.fn_SetValue = function(row) {
    if (row > 0) {
        //그리드에서 선택시
        scwin.TR_JOB = "U";
        if (scwin.ELW_MBR_INFO_TP_CD == 1) {
            img_COM_NM_1.setDisabled(true);
            btn_SDate_1.setDisabled(true);
            edt_SDate_1.setReadOnly(true);
            edt_EDate_1.setReadOnly(false);
            txb_NotiTitle_1.setReadOnly(false);
            txa_NotiContn_1.setReadOnly(false);
            edt_SDate_1.setStyle("backgroundcolor", "#b9d4f7");
            edt_EDate_1.setStyle("backgroundcolor", "#ffffff");
            txb_NotiTitle_1.setStyle("backgroundcolor", "#ffffff");
            txa_NotiContn_1.style.background = "#ffffff";
            $c.stf.setObjectValue(txb_ISUR_CD_1, dts_List_1.getCellData(eval(row), "ISUR_CD"));
            $c.stf.setObjectValue(txb_COM_NM_1, dts_List_1.getCellData(eval(row), "COM_ABBRV"));
            $c.stf.setObjectValue(txb_NotiTitle_1, dts_List_1.getCellData(eval(row), "NOTI_TITLE"));
            $c.stf.setObjectValue(txa_NotiContn_1, dts_List_1.getCellData(eval(row), "NOTI_CONTN"));
            $c.stf.setObjectValue(edt_SDate_1, dts_List_1.getCellData(eval(row), "STRT_DD"));
            $c.stf.setObjectValue(edt_EDate_1, dts_List_1.getCellData(eval(row), "END_DD"));
        } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
            img_COM_NM_2.setDisabled(true);
            btn_SDate_2.setDisabled(true);
            edt_SDate_2.setReadOnly(true);
            txa_NotiContn_2.setReadOnly(false);
            edt_SDate_2.setStyle("backgroundcolor", "#b9d4f7");
            txa_NotiContn_2.style.background = "#ffffff";
            $c.stf.setObjectValue(txb_ISUR_CD_2, dts_List_2.getCellData(eval(row), "ISUR_CD"));
            $c.stf.setObjectValue(txb_COM_NM_2, dts_List_2.getCellData(eval(row), "COM_ABBRV"));
            $c.stf.setObjectValue(cmb_NotiTitle_2, dts_List_2.getCellData(eval(row), "NOTI_TITLE"));
            $c.stf.setObjectValue(txa_NotiContn_2, dts_List_2.getCellData(eval(row), "NOTI_CONTN"));
            $c.stf.setObjectValue(edt_SDate_2, $c.ut.replaceAll(dts_List_2.getCellData(eval(row), "STRT_DD"), "-", ""));
        } else if (scwin.ELW_MBR_INFO_TP_CD == 3) {
            scwin.fn_Enable_Item();
        } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
            scwin.fn_Enable_Item();
            $c.stf.setObjectValue(txb_NotiTitle_4, dts_List_4.getCellData(eval(row), "NOTI_TITLE"));
            $c.stf.setObjectValue(txa_NotiContn_4, dts_List_4.getCellData(eval(row), "NOTI_CONTN"));
            $c.stf.setObjectValue(edt_SDate_4_1, $c.ut.replaceAll(dts_List_4.getCellData(eval(row), "STRT_DD"), "-", ""));
            $c.stf.setObjectValue(edt_SDate_4_2, $c.ut.replaceAll(dts_List_4.getCellData(eval(row), "END_DD"), "-", ""));
            $c.stf.setObjectValue(txb_INFO_RND_4, dts_List_4.getCellData(eval(row), "INFO_RND"));
        } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
            scwin.fn_Enable_Item();
            $c.stf.setObjectValue(txb_NotiTitle_5, dts_List_5.getCellData(eval(row), "NOTI_TITLE"));
            $c.stf.setObjectValue(txa_NotiContn_5, dts_List_5.getCellData(eval(row), "NOTI_CONTN"));
            $c.stf.setObjectValue(edt_SDate_5_1, $c.ut.replaceAll(dts_List_5.getCellData(eval(row), "STRT_DD"), "-", ""));
            $c.stf.setObjectValue(edt_SDate_5_2, $c.ut.replaceAll(dts_List_5.getCellData(eval(row), "END_DD"), "-", ""));
            $c.stf.setObjectValue(txb_INFO_RND_5, dts_List_5.getCellData(eval(row), "INFO_RND"));
        }
    }
};
scwin.fn_Enable_Item = function() {
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        $c.stf.setObjectValue(txb_ISUR_CD_1, "");
        $c.stf.setObjectValue(txb_COM_NM_1, "");
        $c.stf.setObjectValue(txb_NotiTitle_1, "");
        $c.stf.setObjectValue(txa_NotiContn_1, "");
        $c.stf.setObjectValue(edt_SDate_1, "");
        $c.stf.setObjectValue(edt_EDate_1, "");
        $c.stf.setObjectValue(txa_NotiContn_1, "");
        img_COM_NM_1.setDisabled(false);
        btn_SDate_1.setDisabled(false);
        txb_NotiTitle_1.setReadOnly(false);
        edt_SDate_1.setReadOnly(false);
        edt_EDate_1.setReadOnly(false);
        txa_NotiContn_1.setReadOnly(false);
        txb_NotiTitle_1.setStyle("backgroundcolor", "#ffffff");
        edt_SDate_1.setStyle("backgroundcolor", "#ffffff");
        edt_EDate_1.setStyle("backgroundcolor", "#ffffff");
        txa_NotiContn_1.style.background = "#ffffff";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        $c.stf.setObjectValue(txb_ISUR_CD_2, "");
        $c.stf.setObjectValue(txb_COM_NM_2, "");
        $c.stf.setObjectValue(txa_NotiContn_2, "");
        $c.stf.setObjectValue(cmb_NotiTitle_2, "");
        $c.stf.setObjectValue(edt_SDate_2, "");
        img_COM_NM_2.setDisabled(false);
        btn_SDate_2.setDisabled(false);
        edt_SDate_2.setReadOnly(false);
        txa_NotiContn_2.setReadOnly(false);
        edt_SDate_2.setStyle("backgroundcolor", "#ffffff");
        txa_NotiContn_2.style.background = "#ffffff";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
        $c.stf.setObjectValue(txb_NotiTitle_4, "");
        $c.stf.setObjectValue(txa_NotiContn_4, "");
        $c.stf.setObjectValue(edt_SDate_4_1, "");
        $c.stf.setObjectValue(edt_SDate_4_2, "");
        $c.stf.setObjectValue(txb_INFO_RND_4, "");
        btn_SDate_4_1.setDisabled(false);
        btn_SDate_4_2.setDisabled(false);
        edt_SDate_4_1.setReadOnly(false);
        edt_SDate_4_2.setReadOnly(false);
        txb_NotiTitle_4.setReadOnly(false);
        txa_NotiContn_4.setReadOnly(false);
        txb_NotiTitle_4.setStyle("backgroundcolor", "#ffffff");
        txa_NotiContn_4.style.background = "#ffffff";
        edt_SDate_4_1.setStyle("backgroundcolor", "#ffffff");
        edt_SDate_4_2.setStyle("backgroundcolor", "#ffffff");
    } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
        $c.stf.setObjectValue(txb_NotiTitle_5, "");
        $c.stf.setObjectValue(txa_NotiContn_5, "");
        $c.stf.setObjectValue(edt_SDate_5_1, "");
        $c.stf.setObjectValue(edt_SDate_5_2, "");
        $c.stf.setObjectValue(txb_INFO_RND_5, "");
        btn_SDate_5_1.setDisabled(false);
        btn_SDate_5_2.setDisabled(false);
        edt_SDate_5_1.setReadOnly(false);
        edt_SDate_5_2.setReadOnly(false);
        txb_NotiTitle_5.setReadOnly(false);
        txa_NotiContn_5.setReadOnly(false);
        txb_NotiTitle_5.setStyle("backgroundcolor", "#ffffff");
        txa_NotiContn_5.style.background = "#ffffff";
        edt_SDate_5_1.setStyle("backgroundcolor", "#ffffff");
        edt_SDate_5_2.setStyle("backgroundcolor", "#ffffff");
    }
};
scwin.fn_Disable_Item = function() {
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        $c.stf.setObjectValue(txb_ISUR_CD_1, "");
        $c.stf.setObjectValue(txb_COM_NM_1, "");
        $c.stf.setObjectValue(txb_NotiTitle_1, "");
        $c.stf.setObjectValue(txa_NotiContn_1, "");
        $c.stf.setObjectValue(edt_SDate_1, "");
        $c.stf.setObjectValue(edt_EDate_1, "");
        img_COM_NM_1.setDisabled(true);
        btn_SDate_1.setDisabled(true);
        txb_NotiTitle_1.setReadOnly(true);
        edt_SDate_1.setReadOnly(true);
        edt_EDate_1.setReadOnly(true);
        txa_NotiContn_1.setReadOnly(true);
        txb_NotiTitle_1.setStyle("backgroundcolor", "#b9d4f7");
        edt_SDate_1.setStyle("backgroundcolor", "#b9d4f7");
        edt_EDate_1.setStyle("backgroundcolor", "#b9d4f7");
        txa_NotiContn_1.style.background = "#b9d4f7";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        $c.stf.setObjectValue(txb_ISUR_CD_2, "");
        $c.stf.setObjectValue(txb_COM_NM_2, "");
        $c.stf.setObjectValue(edt_SDate_2, "");
        $c.stf.setObjectValue(cmb_NotiTitle_2, "");
        $c.stf.setObjectValue(txa_NotiContn_2, "");
        img_COM_NM_2.setDisabled(true);
        btn_SDate_2.setDisabled(true);
        edt_SDate_2.setReadOnly(true);
        txa_NotiContn_2.setReadOnly(true);
        edt_SDate_2.setStyle("backgroundcolor", "#b9d4f7");
        txa_NotiContn_2.style.background = "#b9d4f7";
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
        $c.stf.setObjectValue(txb_NotiTitle_4, "");
        $c.stf.setObjectValue(txa_NotiContn_4, "");
        $c.stf.setObjectValue(edt_SDate_4_1, "");
        $c.stf.setObjectValue(edt_SDate_4_2, "");
        $c.stf.setObjectValue(txb_INFO_RND_4, "");
        btn_SDate_4_1.setDisabled(true);
        btn_SDate_4_2.setDisabled(true);
        edt_SDate_4_1.setReadOnly(true);
        edt_SDate_4_2.setReadOnly(true);
        txb_NotiTitle_4.setReadOnly(true);
        txa_NotiContn_4.setReadOnly(true);
        txb_NotiTitle_4.setStyle("backgroundcolor", "#b9d4f7");
        txa_NotiContn_4.style.background = "#b9d4f7";
        edt_SDate_4_1.setStyle("backgroundcolor", "#b9d4f7");
        edt_SDate_4_2.setStyle("backgroundcolor", "#b9d4f7");
    } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
        $c.stf.setObjectValue(txb_NotiTitle_5, "");
        $c.stf.setObjectValue(txa_NotiContn_5, "");
        $c.stf.setObjectValue(edt_SDate_5_1, "");
        $c.stf.setObjectValue(edt_SDate_5_2, "");
        $c.stf.setObjectValue(txb_INFO_RND_5, "");
