        btn_SDate_5_2.setDisabled(true);
        edt_SDate_5_1.setReadOnly(true);
        edt_SDate_5_2.setReadOnly(true);
        txb_NotiTitle_5.setReadOnly(true);
        txa_NotiContn_5.setReadOnly(true);
        txb_NotiTitle_5.setStyle("backgroundcolor", "#b9d4f7");
        txa_NotiContn_5.style.background = "#b9d4f7";
        edt_SDate_5_1.setStyle("backgroundcolor", "#b9d4f7");
        edt_SDate_5_2.setStyle("backgroundcolor", "#b9d4f7");
    }
};
scwin.fn_list_sync = function() {
    scwin.fn_Disable_Item();
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        // 상장제한종목	
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName&outputMessageId=ELW_ULY_CHG_INFO_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.select.elw.list.isu.lmt.condition" + "&{P}ELW_MBR_INFO_TP_CD=1" + "&{P}CHK_YN=" + $c.stf.getObjectValue(chk_DelYn);
        dts_List_1.DataID = encodeURI(url);
        dts_List_1.Reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        // 지수구성종목변동
        var url = "/ElwListedReceive.do?method=listElwUlyChgInfo&inputMessageId=ELW_ULY_CHG_INFO_INOUT";
        url += "&ELW_MBR_INFO_TP_CD=2";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.Reset();
        $c.cm.ShowWin(grd_List_2);
    } else if (MaxTab_01.getSelectedTabIndex() == 3) {
        // 발행가능 스타지수 기초자산
        var url = "/ElwListedReceive.do?method=listElwStarIndexByTop5Com&inputMessageId=ELW_STARIDX_BYMM_TOP5_COM_INOUT";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&BAS_YYMM=" + $c.stf.getObjectValue(txb_YYYYMM);
        dts_List_3.DataID = encodeURI(url);
        dts_List_3.Reset();
        $c.cm.ShowWin(grd_List_3);
    } else if (MaxTab_01.getSelectedTabIndex() == 4) {
        // 심사서류첨부
        var url = "/ElwListedReceive.do?method=listElwExchDeclInfo&inputMessageId=ELW_EXCH_DECL_INFO_INOUT";
        url += "&ELW_MBR_INFO_TP_CD=3";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_4.DataID = encodeURI(url);
        dts_List_4.Reset();
        $c.cm.ShowWin(grd_List_4);
    } else if (MaxTab_01.getSelectedTabIndex() == 5) {
        // 기타안내
        var url = "/ElwListedReceive.do?method=listElwExchDeclInfo&inputMessageId=ELW_EXCH_DECL_INFO_INOUT";
        url += "&ELW_MBR_INFO_TP_CD=4";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_5.DataID = encodeURI(url);
        dts_List_5.Reset();
        $c.cm.ShowWin(grd_List_5);
    } else if (MaxTab_01.getSelectedTabIndex() == 6) {
        // 발행가능  KOSPI 200 기초자산
        var url = "/ElwListedReceive.do?method=listElwUlyNmInfo&inputMessageId=ELW_ULY_NM_INOUT";
        url += "&ELW_MBR_INFO_TP_CD=6&BAS_YYMM=" + $c.stf.getObjectValue(cmb_Bas_YYMM);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_6.DataID = encodeURI(url);
        dts_List_6.Reset();
        $c.cm.ShowWin(grd_List_6);
    } else if (MaxTab_01.getSelectedTabIndex() == 7) {
        // 발행가능행사가격
        var url = "/ElwListedReceive.do?method=listElwIsuPosblExerPrcInfo&inputMessageId=ELW_ISU_POSBL_EXER_PRC_INOUT";
        url += "&ELW_MBR_INFO_TP_CD=7&BAS_YYMM=" + $c.stf.getObjectValue(txb_YYYYMM);
        url += "&RGHT_TP_CD=" + $c.stf.getObjectValue(rdo_RGHT_TP_CD);
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List_7.DataID = encodeURI(url);
        dts_List_7.Reset();
        $c.cm.ShowWin(grd_List_7);
    }
};
