};
scwin.fn_CheckForm = function() {
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        if ($c.stf.getObjectValue(txb_ISUR_CD_1) == "") {
            $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_1) == "") {
            $c.win.alert("[제한사유 발생시점]을 입력하세요.");
            edt_SDate_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_EDate_1) == "") {
            $c.win.alert("[제한사유 종료시점]을 입력하세요.");
            edt_EDate_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_NotiTitle_1) == "") {
            $c.win.alert("[제한사유]를 입력하세요.");
            txb_NotiTitle_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_1) > $c.stf.getObjectValue(edt_EDate_1)) {
            $c.win.alert("[제한사유 종료시점]을  이전으로 입력하세요.");
            edt_SDate_1.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        if ($c.stf.getObjectValue(txb_ISUR_CD_2) == "") {
            $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_2) == "") {
            $c.win.alert("[지수편출일]을 입력하세요.");
            edt_SDate_2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_NotiTitle_2) == "") {
            $c.win.alert("[지수구분]을 선택하세요.");
            cmb_NotiTitle_2.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD == 3) {
        if ($c.stf.getObjectValue(txb_ISUR_CD_1_1) == "") {
            $c.win.alert("[종목명]를 입력하세요.");
            txb_ISUR_CD_1_1.focus();
            return false;
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
        if (scwin.TR_JOB != "D") {
            if ($c.stf.getObjectValue(txb_NotiTitle_4) == "") {
                $c.win.alert("[제목]을 입력하세요.");
                txb_NotiTitle_4.focus();
                return false;
            }
            if ($c.stf.getObjectValue(txa_NotiContn_4) == "") {
                $c.win.alert("[내용]을 입력하세요.");
                txa_NotiContn_4.focus();
                return false;
            } else {
                var vtxa_NotiContn_4 = $c.stf.getObjectValue(txa_NotiContn_4);
                if ($c.stf.fn_chkXss(vtxa_NotiContn_4)) {
                    $c.win.alert("허용되지 않는 문자가 들어가 있습니다.");
                    txa_NotiContn_4.focus();
                    return false;
                }
            }
            if ($c.stf.getObjectValue(edt_SDate_4_1) == "") {
                $c.win.alert("[메시지 표시기간]을 입력하세요.");
                edt_SDate_4_1.focus();
                return false;
            }
            if ($c.stf.getObjectValue(edt_SDate_4_2) == "") {
                $c.win.alert("[메시지 표시기간]을 입력하세요.");
                edt_SDate_4_2.focus();
                return false;
            }
            if ($c.stf.getObjectValue(edt_SDate_4_1) > $c.stf.getObjectValue(edt_SDate_4_2)) {
                $c.win.alert("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.");
                edt_SDate_4_1.focus();
                return false;
            }
        }
    } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
        if ($c.stf.getObjectValue(txb_NotiTitle_5) == "") {
            $c.win.alert("[제목]을 입력하세요.");
            txb_NotiTitle_5.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txa_NotiContn_5) == "") {
            $c.win.alert("[내용]을 입력하세요.");
            txa_NotiContn_5.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_5_1) == "") {
            $c.win.alert("[메시지 표시기간]을 입력하세요.");
            edt_SDate_5_1.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_5_2) == "") {
            $c.win.alert("[메시지 표시기간]을 입력하세요.");
            edt_SDate_5_2.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_SDate_5_1) > $c.stf.getObjectValue(edt_SDate_5_2)) {
            $c.win.alert("[메시지 표시기간]의 시작일자는 종료일자보다 작아야 합니다.");
            edt_SDate_5_1.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_trs = function() {
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.TR_JOB == "I") vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.TR_JOB == "U") vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;

    else if (scwin.TR_JOB == "D") vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    if (scwin.ELW_MBR_INFO_TP_CD == 1) {
        dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD_1));
        dts_Item.setCellData(1, "NOTI_TITLE", $c.stf.getObjectValue(txb_NotiTitle_1));
        dts_Item.setCellData(1, "NOTI_CONTN", $c.stf.getObjectValue(txa_NotiContn_1));
        dts_Item.setCellData(1, "STRT_DD", $c.stf.getObjectValue(edt_SDate_1));
        dts_Item.setCellData(1, "END_DD", $c.stf.getObjectValue(edt_EDate_1));
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwUlyChgInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD == 2) {
        dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD_2));
        dts_Item.setCellData(1, "NOTI_TITLE", $c.stf.getObjectValue(cmb_NotiTitle_2));
        dts_Item.setCellData(1, "NOTI_CONTN", $c.stf.getObjectValue(txa_NotiContn_2));
        dts_Item.setCellData(1, "STRT_DD", $c.stf.getObjectValue(edt_SDate_2));
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwUlyChgInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD == 4) {
        dts_Item.setCellData(1, "NOTI_TITLE", $c.stf.getObjectValue(txb_NotiTitle_4));
        dts_Item.setCellData(1, "NOTI_CONTN", $c.stf.getObjectValue(txa_NotiContn_4));
        dts_Item.setCellData(1, "STRT_DD", $c.stf.getObjectValue(edt_SDate_4_1));
        dts_Item.setCellData(1, "END_DD", $c.stf.getObjectValue(edt_SDate_4_2));
        dts_Item.setCellData(1, "INFO_RND", $c.stf.getObjectValue(txb_INFO_RND_4));
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", "3");
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwExchDeclInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    } else if (scwin.ELW_MBR_INFO_TP_CD == 5) {
        dts_Item.setCellData(1, "NOTI_TITLE", $c.stf.getObjectValue(txb_NotiTitle_5));
        dts_Item.setCellData(1, "NOTI_CONTN", $c.stf.getObjectValue(txa_NotiContn_5));
        dts_Item.setCellData(1, "STRT_DD", $c.stf.getObjectValue(edt_SDate_5_1));
        dts_Item.setCellData(1, "END_DD", $c.stf.getObjectValue(edt_SDate_5_2));
        dts_Item.setCellData(1, "INFO_RND", $c.stf.getObjectValue(txb_INFO_RND_5));
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", "4");
        trs_Save.Action = "/ElwListedReceive.do?method=saveElwExchDeclInfo&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD;
    }
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";

    //alert(dts_Item.Text);
    trs_Save.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", scwin.ELW_MBR_INFO_TP_CD);
        dts_Item.setCellData(1, "EMP_NO", js_id);
        scwin.fn_trs();
    }
};
scwin.fn_delete = function() {
    scwin.TR_JOB = "D";
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "TR_JOB", scwin.TR_JOB);
        dts_Item.setCellData(1, "ELW_MBR_INFO_TP_CD", scwin.ELW_MBR_INFO_TP_CD);
        scwin.fn_trs();
    }
};
