scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    if (nIndex == 6) {
        // 	발행가능 KOSPI200 기초자산		
        $c.stf.setObjectValue(txb_basYm, "분기");
        cmb_Bas_YYMM.setSelectedIndex(1);
        $c.stf.setObjectValue(cmb_Bas_YYMM, $c.cp.valueOfIndex(cmb_Bas_YYMM, "VALUE", cmb_Bas_YYMM.getSelectedIndex()));
        $c.stf.showObj(txb_basYm, true);
        $c.stf.showObj(cmb_Bas_YYMM, true);
        $c.stf.showObj(label_26, false);
        $c.stf.showObj(rdo_RGHT_TP_CD, false);
        $c.stf.showObj(txb_YYYYMM, false);
    } else if (nIndex == 3) {
        //	발행가능 스타지수 기초자산 
        $c.stf.setObjectValue(txb_basYm, "기준년월");
        scwin.fn_setYYYYMM();
        $c.stf.showObj(txb_basYm, true);
        $c.stf.showObj(cmb_Bas_YYMM, false);
        $c.stf.showObj(label_26, false);
        $c.stf.showObj(rdo_RGHT_TP_CD, false);
        $c.stf.showObj(txb_YYYYMM, true);
    } else if (nIndex == 7) {
        //	발행가능 행사가격
        $c.stf.setObjectValue(txb_basYm, "기준년월");
        scwin.fn_setYYYYMM();
        $c.stf.showObj(txb_basYm, true);
        $c.stf.showObj(cmb_Bas_YYMM, false);
        $c.stf.showObj(label_26, true);
        $c.stf.showObj(rdo_RGHT_TP_CD, true);
        $c.stf.showObj(txb_YYYYMM, true);
    } else {
        $c.stf.showObj(txb_basYm, false);
        $c.stf.showObj(cmb_Bas_YYMM, false);
        $c.stf.showObj(label_26, false);
        $c.stf.showObj(rdo_RGHT_TP_CD, false);
        $c.stf.showObj(txb_YYYYMM, false);
    }
    scwin.ELW_MBR_INFO_TP_CD = nIndex;
    scwin.fn_SetTitle();
    scwin.fn_SetDataHeader();
    scwin.fn_list_sync();
    scwin.fn_SetTitle();
};
