scwin.btn_Search_onclick = function() {
    if (scwin.ELW_MBR_INFO_TP_CD == 7) {
        if ($c.stf.getObjectValue(rdo_RGHT_TP_CD) == "") {
            $c.win.alert("권리형태를 지정해주세요.");
            rdo_RGHT_TP_CD.focus();
            return;
        }
        if ($c.stf.getObjectValue(txb_YYYYMM) == "") {
            $c.win.alert("기준년월을 지정해주세요.");
            txb_YYYYMM.focus();
            return;
        } else {
            if ($c.stf.getObjectValue(txb_YYYYMM).length < 6) {
                $c.win.alert("올바른 날짜형식이 아닙니다.(YYYYMM)");
                txb_YYYYMM.focus();
                return;
            } else {
                if ($c.stf.getObjectValue(txb_YYYYMM).substr(0, 1) < 1) {
                    $c.win.alert("올바른 날짜형식이 아닙니다.");
                    txb_YYYYMM.focus();
                    return;
                }
                if ($c.stf.getObjectValue(txb_YYYYMM).substr(4, 2) > 12 || $c.stf.getObjectValue(txb_YYYYMM).substr(4, 2) < 1) {
                    $c.win.alert("올바른 날짜형식이 아닙니다.");
                    txb_YYYYMM.focus();
                    return;
                }
            }
        }
    }
    scwin.fn_list_sync();
};
